with v(id,beschr,website,missie,plaats,bmin,bmax,btoel,bron) as (values
('b719dad1-7e0b-49c0-8d4d-af0584032664','De Karl Kahane Foundation is een onafhankelijke, privaat gefinancierde Zwitserse stichting zonder politieke of religieuze binding. Aandachtsgebieden zijn toegankelijkheid, migratie en integratie, en sociale mobiliteit. De stichting steunt projecten in Oostenrijk, Jordanië, Libanon, Bulgarije, Tsjechië, Moldavië en Oekraïne. Doelgroepen zijn onder meer kinderen uit gezinnen met een laag inkomen (toegang tot goed onderwijs), vluchtelingen en ontheemden (zoals Syriërs in Libanon en Jordanië), kwetsbare Libanese en Palestijnse groepen, kinderen met speciale behoeften en hun gezinnen, jongeren met een beperking en kinderen die in instellingen zijn opgegroeid. Het Jubilee Gift-programma staat niet open voor ongevraagde aanvragen.',null,null,null,null,null,null,'https://www.karlkahanefoundation.org/?p=950'),
('4c827c09-5ce5-44f4-a7c1-3b5725283e65','Het Kiwanis Children''s Fund financiert met club grants lokale serviceprojecten van Kiwanisclubs voor kinderen. Aandachtsgebieden: gezondheid en voeding, onderwijs en geletterdheid, leiderschapsontwikkeling van jongeren, aangepast spelen en toegankelijkheid voor kinderen met een beperking, en gemeenschapsontwikkeling. Aanvragers zijn Kiwanisclubs, eventueel samen met lokale partnerorganisaties; ngo''s werken dus via een lokale club. Het fonds werkt internationaal (VS, Canada en elders) met een jaarlijkse aanvraagcyclus. Er zijn geen minimum- of maximumbedragen gepubliceerd.',null,null,null,null,null,null,'https://grantable.co/grants/kiwanis-children-s-fund-club-grants-b50d95ceafe7'),
('7471c948-db69-423b-9e9f-30bb1473d625','De Lions Clubs International Foundation financiert humanitaire projecten van Lionsclubs en -districten wereldwijd; externe organisaties werken via een lokale club. Er zijn verschillende subsidietypes: matching grants voor apparatuur en bouw bij grootschalige projecten voor onvervulde humanitaire behoeften (US$10.000–150.000), community impact grants voor lokale projecten, en programma''s voor diabeteszorg, oogzorg en blindheidspreventie (SightFirst), hongerbestrijding (schoolmaaltijden, voedselbanken), kinderkanker (samen met medische instellingen, US$10.000–150.000), noodhulp en rampenparaatheid, Leo-serviceprojecten en Lions Quest (sociaal-emotioneel leren op scholen). Focusgebieden zijn zicht, noodhulp, jeugd en humanitaire hulp.',null,null,null,null,null,'LCIF Grants Toolkit: matching grants en kinderkankergrants US$10.000–US$150.000 (in dollars, niet omgerekend).','https://lionsclubs.org/en/lcif-grants-toolkit'),
('93e2910a-99ee-4ac1-8376-562d5bed9b55','Het Madurodam Kinderfonds wil kinderen helpen zich te ontwikkelen tot actieve, verantwoordelijke burgers. Het fonds versterkt zelfvertrouwen, zelfredzaamheid, moed en initiatief, onder het motto ''Empathie in actie''. Thema''s zijn empathie, actief burgerschap, ontmoeting buiten de eigen kring en een koppeling met de SDG''s. Doelgroep: kinderen van 0 tot 18 jaar, met nadruk op 10-18 jaar, in het Koninkrijk der Nederlanden; de voorkeur gaat naar de regio Den Haag en het Caribisch deel. Het fonds geeft giften aan ANBI-organisaties, voert eigen projecten uit en ondersteunt challenges van het jeugdcollege van Madurodam. Niet gesteund: wetenschappelijk onderzoek, commerciële, politieke of religieuze projecten, individuen, structurele steun, sportclubs, scouting, speeltuinen en festivals.',null,null,null,null,null,null,'https://www.madurodam.nl/sites/madurodam_corp/files/inline-files/beleid%20MKF%202021%202023_0.pdf'),
('082d3fd3-caf6-465f-a88c-ef1ae3bee159','Mama Cash is een internationaal feministisch fonds. Het Spark Fund steunt zelfgeleide groepen in Nederland en op Aruba, Bonaire, Curaçao, Saba, Sint Eustatius en Sint Maarten die werken aan urgente en omstreden politieke vraagstukken en structurele verandering. Het werk moet uitgaan van een feministisch perspectief of van de rechten van vrouwen, meisjes, trans- en intersekse personen. De groepen worden geleid door de mensen die zij dienen. Voorrang gaat naar informele of niet-geregistreerde groepen, nieuwe groepen, vrijwilligersgroepen en groepen met weinig middelen. Een bankrekening, verblijfsvergunning of stichtingsvorm is niet nodig. Aanvragen kan schriftelijk, op video of als audio, in het Nederlands of Engels; de aanvraagronde opent meestal in augustus.',null,null,null,5000,12000,'Website Spark Fund (2026): €5.000–€12.000 per project, looptijd tot twee jaar.','https://www.mamacash.org/funds/spark-fund'),
('bee51018-e121-4847-acfe-c0f044e4071b','Deze tijdelijke subsidieregeling steunt maatschappelijke initiatieven rond het trans-Atlantische slavernijverleden voor nazaten van tot slaaf gemaakten op Curaçao, Aruba, Sint Maarten, Bonaire, Sint Eustatius en Saba. Doelen zijn meer begrip van de doorwerking van het slavernijverleden, verwerking, kennis en bewustwording, erkenning en herdenking. Subsidie is mogelijk voor de professionalisering van organisaties die aan deze doelen werken (voucher van €10.000) en voor maatschappelijke initiatieven die de gemeenschap versterken. Aanvragers zijn niet-overheidsorganisaties en private partijen die in het Caribisch deel zijn geregistreerd; samenwerking tussen eilanden is mogelijk. Exploitatiekosten en herstelbetalingen vallen buiten de regeling. De regeling loopt van 2024 tot 2029 in meerdere aanvraagperioden.',null,null,null,10000,500000,'Regelingstekst (internetconsultatie, 2024): maatschappelijke initiatieven €10.000–€500.000, professionaliseringsvoucher €10.000.','https://internetconsultatie.nl/slavernijverledencaribisch/document/12374'),
('4759bbc9-99c0-4240-800e-aa14c7e158ff','Het Mohamed bin Zayed Species Conservation Fund geeft gerichte, kleine subsidies aan veldprojecten voor de bescherming van bedreigde soorten. Het erkent ook leiders in soortbescherming en wil soorten meer aandacht geven in het bredere natuurbeschermingsdebat. Projecten kunnen gaan over plant-, dier- en schimmelsoorten, zonder beperking naar regio of soort; projecten die niet om een bedreigde soort draaien worden ontmoedigd. Natuurbeschermers uit de hele wereld kunnen aanvragen, in het Engels en met een begroting in Amerikaanse dollars. De bijdrage is maximaal US$25.000 per project; de totale projectbegroting mag hoger zijn als er cofinanciering is. Het fonds heeft meer dan 2.000 subsidies toegekend.',null,null,null,null,null,'Opportunity Desk (2020): maximaal US$25.000 per project (in dollars, niet omgerekend).','https://opportunitydesk.org/2020/09/16/mohamed-bin-zayed-species-conservation-fund-2020'),
('2c854b2c-7240-4e80-b2e8-45f4a490baca','Het Mondriaan Fonds is het publieke fonds voor beeldende kunst en cultureel erfgoed in Nederland en het Caribisch deel van het Koninkrijk. Het steunt beeldend kunstenaars (startende en gevestigde), curatoren, critici en theoretici, musea, erfgoedinstellingen, kunstpodia, galeries, uitgevers en opdrachtgevers van kunst. Regelingen dekken onder meer werkbijdragen voor kunstenaars, projecten, residencies, publicaties, presentaties van kunst en erfgoed, aankopen en collectiemobiliteit voor musea, programma''s van kunstpodia, beschermd cultuurgoed, restauratie van mobiel erfgoed, erfgoedinnovatie, erfgoedvrijwilligers, internationale presentaties en vouchers voor ontwikkeling en reizen. Ook waren er open oproepen rond het herdenkingsjaar slavernijverleden en kunst en media. Het werk moet bijdragen aan de beeldende kunst- of erfgoedsector.',null,null,null,null,null,'Jaarverslag 2023: bedragen per regeling, bijv. vouchers tot €2.500, Kunstenaar Start €22.000, Kunstenaar Basis €44.000, programma''s kunstpodia tot €275.000 per jaar.','https://rapportages.mondriaanfonds.nl/app/uploads/2025/11/Mondriaan-Fonds-Jaarverslag-en-toekenningen-2023.pdf'),
('8b691e04-f9da-44bb-8bdd-8fe247158a6d','Het Nederlands Filmfonds is het rijkscultuurfonds voor film. Het stimuleert films van eigenzinnige kwaliteit en geeft makers ruimte om een eigen stem te ontwikkelen. De pijlers zijn talentontwikkeling, innovatie, internationalisering en professionalisering, plus sectorbeleid. Het fonds steunt ontwikkeling en productie van speelfilms, documentaires, animatie en korte films; talentprogramma''s voor afgestudeerden; experimentele en immersieve projecten; minoritaire coproducties; distributie, vertoning en filmfestivals; en jeugd- en kinderfilm. Via de Netherlands Film Production Incentive krijgen speelfilms en high-end series een cash rebate op productiekosten in Nederland. De Netherlands Film Commission ondersteunt de filmsector. Aanvragers zijn scenaristen, regisseurs, onafhankelijke producenten en festivals.',null,null,null,null,null,'Jaarverslag 2019: bedragen per regeling, bijv. Wildcards €50.000, Filmfonds Shorts €40.000, ontwikkeling tot circa €90.000.','https://catalogus.boekman.nl/pub/Filmfonds/2019.pdf'),
('1bd07c47-2301-4a0b-8118-9139c957763d','Het Nederlands Letterenfonds is het rijkscultuurfonds voor literatuur. Het ondersteunt schrijvers en vertalers van literair werk met projectsubsidies en ontwikkelsubsidies. Projectsubsidies zijn bedoeld voor het schrijven of vertalen van een boek, of voor literair werk in een andere vorm, zoals een podcast. Ontwikkelsubsidies zijn voor de eigen groei als schrijver of vertaler, bijvoorbeeld via een opleiding, coaching of een onderzoeksreis. Het fonds richt zich op de Nederlandstalige literatuur en vertalingen. Voorwaarden en deadlines verschillen per regeling; een subsidiewijzer helpt bij het kiezen.',null,null,null,null,null,null,'https://ondernemersplein.overheid.nl/subsidies-en-regelingen/schrijvers-vertalers-biografen/'),
('e70c2f0d-1015-4bba-84aa-80e84d7a4a2e','De Œuvre Nationale de Secours Grande-Duchesse Charlotte is een Luxemburgs nationaal fonds, opgericht in 1944 en gefinancierd uit de opbrengsten van de Loterie nationale. Het steunt projecten op het gebied van sport, gezondheid, sociaal welzijn, milieu en cultuur. Het geld gaat onder meer naar het Fonds national de solidarité, de sociale diensten en vaste partners zoals Rode Kruis en Caritas, maar ook naar eenmalige giften aan verenigingen (bijvoorbeeld patiëntenorganisaties). Er is een startfonds voor kunstenaars onder de 35 jaar, en er zijn thematische projectoproepen, zoals voor milieuprojecten die de ecologische voetafdruk van Luxemburg verkleinen. Het fonds stelt prioriteiten op basis van signalen van verenigingen in het veld.',null,null,null,null,null,null,'https://paperjam.lu/article/news-mieux-repondre-aux-besoins-du-terrain'),
('4ec76b76-3d7d-462e-bf8b-e98b273d4782','Het openbaar lichaam Sint Eustatius verstrekt op basis van de Subsidieverordening 2020 taaksubsidies aan organisaties en stichtingen die namens het openbaar lichaam een essentiële dienst aan de gemeenschap leveren. Activiteiten moeten de gemeenschap ten goede komen, aansluiten bij het overheidsbeleid of wettelijke taken, en niet door de overheid zelf worden uitgevoerd. Aanvragers moeten deskundig zijn en eigen inkomsten kunnen genereren. Aanvragen worden in april van het voorgaande jaar ingediend. Beleidsterreinen zijn onder meer toerisme, kleinbedrijf en ondernemerschap, sociale huisvesting, natuur en milieu (parkbeheer), erfgoed, bibliotheek, sport en jeugdzorg. Daarnaast zijn er projectfinancieringen en speciale bijdragen buiten de verordening. Verantwoordingseisen hangen af van de hoogte van de subsidie.',null,null,null,null,null,null,'https://www.statiagovernment.com/binaries/sint-eustatius-en/documenten/publications/2021/04/23/20210422-subsidies-presentation/20210422+Subsidies+Presentation.pdf'),
('77a02f08-6e35-4849-a948-85fe48210fae','Sponsorprogramma van Princess Juliana International Airport op Sint Maarten voor commerciële initiatieven en maatschappelijke programma''s. Ondersteund worden initiatieven op het gebied van onderwijs, gezondheidszorg, milieu, gemeenschap en cultuur, met accent op educatie, hospitality en zorg. Non-profit- en gemeenschapsaanvragen moeten blijvend lokaal voordeel opleveren en passen bij het imago van de luchthaven; langdurige betrokkenheid wordt gewaardeerd. Steun kan bestaan uit geld (in USD), promotiemateriaal of vrijwilligers. Aanvragen gaan uitsluitend via het online formulier, minimaal acht weken vooraf; jaarlijkse of partnerschapsaanvragen vóór eind november van het voorgaande jaar. Gesponsorde partijen leveren binnen 30 dagen een evenementrapport en geven de luchthaven zichtbaarheid (logo, vermelding, promotiemateriaal). Geschikt voor lokale evenementen, sport, cultuur, onderwijs- en zorgactiviteiten op Sint Maarten.',null,null,null,null,null,null,'https://www.sxmairport.com/community-events/sponsorships'),
('566d1768-da20-44b3-be67-d8ef8308d7aa','Particulier, onafhankelijk fonds dat al ruim zestig jaar cultuur- en natuurinitiatieven steunt op de zes eilanden van het Caribisch deel van het Koninkrijk: Curaçao, Aruba, Sint Maarten, Bonaire, Sint Eustatius en Saba. Het fonds verleent (gedeeltelijke) bijdragen aan vernieuwende en inspirerende projecten die cultuur en natuur toegankelijk maken, tonen, behouden of beschermen. Werkvelden: geschiedenis en letteren, beeldende kunst, podiumkunsten (muziek, dans, theater), kunst- en cultuureducatie, natuurbehoud en monumentenzorg. Aanvragen worden online ingediend; aanvragen onder ANG 10.000 worden maandelijks beoordeeld, aanvragen tot ANG 25.000 per kwartaal. Het fonds is daarnaast aanspreekpunt voor makers in Caribisch Nederland in samenwerking met de rijkscultuurfondsen.','https://pbccaribbean.com','Ondersteunen van cultuur- en natuurinitiatieven en -ontwikkeling op de zes eilanden van het Caribisch deel van het Koninkrijk.',null,null,null,'NPower SXM-fondsenoverzicht: gedeeltelijke bijdragen tot ANG 25.000 (bedrag in Antilliaanse guldens, niet omgerekend).','https://www.npowersxm.com/grants/prins-bernhard-culture-fund-caribbean'),
('632ae28a-fdf1-40a7-a55e-7fd44e5b0706','Pilotsubsidieregeling van de Rijksdienst voor het Cultureel Erfgoed voor het onderhoud van monumentale woonhuizen op Bonaire, Sint Eustatius en Saba. Particuliere eigenaren van een monument met een woonfunctie kunnen een bijdrage aanvragen in de kosten van onderhoud. De pilot heeft twee doelen: eigenaren financieel ondersteunen bij het in stand houden van hun monumentale woning en praktijkervaring opdoen met het subsidiëren van monumentenonderhoud in Caribisch Nederland. De aanvraagperiode in 2026 liep van 1 tot en met 30 september; besluiten volgen naar verwachting eind februari 2027, waarna ontvangers twee jaar hebben om de werkzaamheden uit te voeren. Werk dat vóór het besluit is gestart of afgerond komt niet in aanmerking. Trefwoorden: monumentenzorg, erfgoedbehoud, onderhoud monumentale panden, restauratie woonhuizen.',null,null,null,null,null,null,'https://english.cultureelerfgoed.nl/topics/s/subsidy-scheme-preservation-monumental-residences-caribbean-netherlands'),
('906e261e-bdc5-432b-a736-1207fbad12a9','Rijkssubsidieregeling, uitgevoerd door RVO, die werkgevers op Bonaire, Sint Eustatius en Saba gedeeltelijk compenseert voor de begeleidingskosten van een leerling of student op een praktijkleerplaats. Doel is beter opgeleid personeel en een betere voorbereiding van jongeren op de arbeidsmarkt. Aanvragers zijn erkende leerbedrijven die een praktijkplaats bieden aan mbo-studenten in de beroepsbegeleidende leerweg (bbl) van een instelling op Bonaire, aan leerlingen in het praktijkonderwijs in hun laatste schooljaar, of aan vmbo-leerlingen in een leerwerktraject of entreeopleiding. Voorwaarden zijn onder meer een minimaal aantal begeleidingsuren per studiejaar en een getekende praktijkovereenkomst. De vergoeding wordt per aanwezigheidsweek berekend en in US-dollars uitbetaald. Trefwoorden: beroepsonderwijs, leerwerkplekken, stages, arbeidstoeleiding jongeren.',null,null,null,null,2800,'Website RVO (2026): maximaal €2.800 per gerealiseerde praktijkleerplaats, uitbetaald in US-dollars.','https://www.rvo.nl/subsidies-financiering/praktijkleren/caribisch-nederland'),
('ef3ebf3b-30d1-4a75-8d10-196a00d88115','Samenwerkingsverband van Nederlandse fondsen (onder meer Oranje Fonds, Kansfonds, Kinderpostzegels en Stichting Sluyterman van Loo) dat sinds 2004 financiële steun geeft aan sociale initiatieven op de eilanden van het Caribisch deel van het Koninkrijk. Doel is maatschappelijke betrokkenheid en gelijke kansen vergroten en mensen die het het meest nodig hebben verder helpen. SFC voert zelf geen projecten uit, maar financiert lokale non-profitorganisaties en biedt advies, netwerk en begeleiding bij aanvragen, inclusief jaarlijkse informatiesessies. Voorbeelden van steunvelden: begeleiding van jongeren na detentie, activiteiten voor ouderen en projecten voor leefbaarheid in de buurt. Er is één gezamenlijk aanvraagformulier voor de deelnemende fondsen; op Aruba fungeert CEDE Aruba als partner en co-financier, op Sint Maarten is een kantoor voor ook Saba en Sint Eustatius.','https://www.samenwerkendefondsencariben.org/en','Financiële steun aan sociale initiatieven op de Caribische eilanden van het Koninkrijk om maatschappelijke betrokkenheid en gelijke kansen te vergroten.',null,null,null,null,'https://thedailyherald.sx/supplements/weekender/samenwerkende-fondsen-cariben-sfc-dedicated-to-making-our-society-a-better-place-for-all'),
('15d4bfaa-7317-4562-ab6d-c364e9a3f6c6','Filantropische stichting van Sandals Resorts die gemeenschappen in het Caribisch gebied ondersteunt via drie pijlers: gemeenschap, onderwijs en milieu. Voorbeelden zijn klaslokalen en schoolverbeteringen, koraalkwekerijen en natuurherstel op zee, en noodhulp na rampen. In het onderwijs financiert de stichting onder meer beurzen (Care for Kids Scholarship Programme, inclusief medische kosten, huisvesting en mentoring), verbetering van schoolfaciliteiten en professionalisering van leraren. Op Curaçao renoveerde de stichting voorzieningen op scholen en verspreidden vrijwilligers schoolpakketten op meerdere scholen. Er is een open call voor het Sandals Foundation Grant Program. Trefwoorden: onderwijs, studiebeurzen, mariene natuurbescherming, koraalherstel, gemeenschapsontwikkeling, rampenhulp.',null,null,null,null,null,null,'https://www.curacaochronicle.com/post/local/sandals-foundation-boosts-caribbean-education-with-usd-110000-in-scholarships-and-school-upgrades'),
('f1536834-f434-49e9-89a3-b02ff02c4b74','Internationaal fonds voor onderzoek, bescherming en educatie rond bedreigde mariene megafauna, met name haaien, roggen, zaagvissen en draakvissen (kraakbeenvissen). Via het Small Grants-programma ondersteunt het innovatieve, kortlopende projecten van 12 tot 18 maanden op het gebied van wetenschappelijk onderzoek, natuurbescherming en educatie. Het programma richt zich op wetenschappers, natuurbeschermers en educatoren aan het begin van hun loopbaan (diploma maximaal vijf jaar geleden behaald) en geeft voorkeur aan lokale projecten onder leiding van lokale projectleiders. Trefwoorden: mariene biologie, haaienbescherming, oceaanbehoud, biodiversiteit, natuureducatie, jonge onderzoekers.',null,null,null,null,null,'Grantable-overzicht Small Grant: bijdragen tot US$5.000 (in dollars, niet omgerekend).','https://grantable.co/grants/save-our-seas-foundation-small-grant-a63de9488ebc'),
('42477b65-e549-4ff3-993f-d2018e7a7d9f','Sponsorprogramma van het Arubaanse telecombedrijf Setar N.V. Sponsoring richt zich op vier kerngebieden: culturele activiteiten, educatie, sociale activiteiten en sport. Steun wordt gegeven in de vorm van een financiële overboeking, merchandise of diensten; contant geld wordt niet verstrekt. Aanvragen moeten passen bij het imago van Setar, vergezeld gaan van een officiële brief en kostenbegroting, en minimaal een maand voor het evenement via de sponsorwebsite worden ingediend. Projecten met religieuze of politieke doelen en persoonlijke feesten of projecten komen niet in aanmerking. Elke organisatie kan maximaal één sponsoring per kalenderjaar ontvangen. Geschikt voor lokale evenementen, sportactiviteiten, culturele en educatieve initiatieven op Aruba.',null,null,null,null,null,null,'https://sponsor.portal.setar.aw'),
('9ec576d8-57f0-4aad-aebe-0a1f8bdda41b','Fonds op Sint Maarten dat programma''s en projecten ontwikkelt en financiert voor sociale en gemeenschapsontwikkeling, met als visie ''A Society That Cares''. Het SMDF werft fondsen, verleent donaties aan projecten, faciliteert de uitvoering en adviseert en monitort projecten. Het steunt lokale ngo''s die werken voor de meest kwetsbare inwoners, zoals pleeggezinnen, noodopvang, activiteiten voor ouderen, naschoolse activiteiten en voedselbanken. Financiering is lokaal en gebaseerd op drie pijlers: sociale empowerment, verbetering van wijken en gemeenschappen, en armoedebestrijding. Jaarlijks is er een deadline eind oktober; daarnaast bestaat een aanvraagmogelijkheid voor incidentele giften. Trefwoorden: armoedebestrijding, wijkverbetering, kwetsbare groepen, ouderen, jeugd, opvang.',null,null,null,null,null,null,'https://www.npowersxm.com/grants/st-maarten-development-fund'),
('4f390c86-51ca-4c53-9d55-272d32f9448a','Landelijke stichting die armoede in Nederland wil voorkomen, verlichten en bestrijden door lokale hulporganisaties te ondersteunen met geld, goederen en kennis. Ruim 1.300 lokale armoedeorganisaties zijn aangesloten. Alleen organisaties kunnen aanvragen, geen individuen; zij melden zich eerst aan via de website. Aangesloten organisaties kunnen enkele keren per jaar projectfinanciering aanvragen, gratis producten afhalen (zoals verzorgingsproducten en wasmiddel) voor mensen in armoede, en gebruikmaken van een verdubbelaar voor eigen fondsenwervingsacties. Daarnaast verzorgt het fonds noodpakketten, menstruatieproducten via uitgiftepunten bij gemeenten en een kennisnetwerk voor hulporganisaties. Trefwoorden: armoedebestrijding, voedsel- en noodhulp in Nederland, menstruatiearmoede, kinderarmoede, hulporganisaties.','https://www.armoedefonds.nl','Armoede in Nederland voorkomen, verlichten en bestrijden door lokale hulporganisaties te ondersteunen met geld, goederen en kennis.',null,null,null,null,'https://www.armoedefonds.nl/wp-content/uploads/2026/05/AF.pdf'),
('16463b9c-69fc-41d2-9156-d7f07aa4ac40','Kinderpostzegels zet zich in voor een wereld die alle kinderen bescherming en ontwikkelingskansen biedt. Internationaal financiert de organisatie projecten die worden uitgevoerd door lokale non-gouvernementele organisaties, onder meer in Guatemala, Nicaragua, Senegal, Mali, Burkina Faso, Ethiopië en India; aanvragen kunnen doorlopend worden ingediend. In het Caribisch deel van het Koninkrijk is Kinderpostzegels partner in Samenwerkende Fondsen Cariben, met een accent op jongeren en sociale betrokkenheid. In Nederland werkt de organisatie samen met partners, bijvoorbeeld rond kinderarmoede (Samen voor Kinder Kansen met het Armoedefonds). Trefwoorden: kinderbescherming, kinderrechten, kansen voor kinderen, kwetsbare kinderen, jeugd, ontwikkelingssamenwerking.',null,null,null,null,null,null,'https://www.girlsnotbrides.org/learning-resources/fundraising/funding-opportunities/kinderpostzegels/'),
('a038bec2-3e6b-499d-bb13-808d61ab96fb','Het Monumentenfonds Curaçao (MFC), opgericht in 1992, bevordert het behoud van het gebouwde erfgoed op Curaçao. Het fonds verstrekt subsidies en zachte leningen aan eigenaren van monumenten voor restauratie en herstel van monumentale panden. Naast financiering biedt het fonds technische begeleiding tijdens restauratietrajecten en geeft het informatie en advies aan (potentiële) aanvragers, architecten en aannemers over juridische, financiële, technische en monumentenzorgaspecten. Het vermogen van het fonds is afkomstig van de overheid en het bedrijfsleven. Trefwoorden: monumentenzorg, restauratie, cultureel erfgoed, historische panden, zachte lening, restauratiesubsidie, Curaçao, Caribisch deel van het Koninkrijk.',null,null,null,null,null,null,'https://dutchculture.nl/location/cura%C3%A7ao-monuments-fund-foundation'),
('25ce0048-6e12-42de-ba05-7d02fd6fed8b','Het Stimuleringsfonds Creatieve Industrie is een rijkscultuurfonds dat in opdracht van het ministerie van OCW subsidies verstrekt aan ontwerpers, makers en culturele instellingen. Het fonds wil de creatieve sector versterken, de kwaliteit en toegankelijkheid van het werk vergroten en ontwerp een centralere rol in de samenleving geven. Het werkt binnen drie disciplines: vormgeving (grafisch en productontwerp), architectuur en digitale cultuur. In de periode 2025-2028 zijn er onder meer regelingen voor vierjarige instellingssubsidies, activiteitenprogramma''s, festivals en publieksactiviteiten, ontwikkeling van vakgebied en praktijk, experiment en Immerse\Interact, aangevuld met programma''s voor talentontwikkeling, internationalisering van de ontwerpsector en ruimtelijk ontwerp. Werkgebied: heel Nederland inclusief het Caribisch deel van het Koninkrijk. Trefwoorden: ontwerp, design, architectuur, digitale cultuur, experiment, talentontwikkeling, internationalisering.',null,null,null,null,null,null,'https://cms.stimuleringsfonds.nl/storage/media/Stimuleringsfonds-Creatieve-Industrie-2025-2028-in-het-kort.pdf'),
('ea4267c8-1ab5-40ff-939f-bf4ca2058909','Het UNESCO Participation Programme is een tweejaarlijks programma dat projecten financiert binnen het mandaat van UNESCO: onderwijs, wetenschap, cultuur en communicatie en informatie. Aanvragen lopen via de nationale UNESCO-commissie; in het Caribisch deel van het Koninkrijk kunnen ngo''s, met name organisaties die met jongeren werken, een projectvoorstel indienen. Voorrang krijgen projecten die meerwaarde hebben voor kleine eilandstaten (SIDS), interdisciplinair werken, gendergelijkheid bevorderen of jongerenparticipatie stimuleren. Vergoed worden onder meer expertise, publicaties en documentatie, vertaling, reiskosten van deelnemers, seminars, webinars en trainingen en studie- of onderzoeksbeurzen; personeels- en administratiekosten niet. UNESCO in Parijs neemt het eindbesluit. Trefwoorden: onderwijs, wetenschap, cultuur, media, jongerenparticipatie, gendergelijkheid, kleine eilandstaten.',null,null,null,null,null,'Oproep Aruba 2026-2027: maximaal US$26.000 per project (bedrag in dollars, niet omgerekend).','https://www.gobierno.aw/en/call-for-applications-for-financial-support-for-projects-under-the-unesco-participation-programme'),
('06fe4bf8-9426-4663-80ba-0b2d5102888b','Vfonds, het Nationaal Fonds voor Vrede, Vrijheid en Veteranenzorg, wil verschillende generaties inspireren en motiveren om bij te dragen aan een sterke democratische rechtsstaat en een vreedzame samenleving, met lessen uit oorlog en conflict als vertrekpunt. Het fonds steunt jaarlijks ruim 200 projecten die kennis over oorlog en conflict vergroten, het belang van en de waardering voor de democratische rechtsstaat bevorderen, mensen vaardigheden bijbrengen om actief bij te dragen aan de samenleving, en waardering tonen voor veteranen en politiemensen. Jongeren zijn een speciale doelgroep. Naast financiering verbindt Vfonds partijen en agendeert het thema''s. Werkgebied: Koninkrijk der Nederlanden. Trefwoorden: vrede, vrijheid, democratie, rechtsstaat, oorlogsherinnering, burgerschap, veteranen, jongeren.',null,null,null,null,null,null,'https://vfonds.nl/about-vfonds'),
('e39226bf-5543-4018-a4b0-a5d71810cb1b','VOCATIO is een Belgische stichting die sinds 1963 jonge talenten ondersteunt die een passie, roeping of levensproject willen waarmaken. Via een jaarlijkse oproep kent de stichting beurzen toe aan gepassioneerde, ondernemende en innovatieve jongeren van 18 tot 30 jaar die financiële steun nodig hebben om hun project te realiseren. De beurzen worden toegekend in uiteenlopende domeinen: medische wetenschappen, sociale en menswetenschappen, wetenschappen en techniek, podiumkunsten, plastische kunsten en ambachten. Trefwoorden: beurs, roeping, levensproject, jong talent, talentontwikkeling, wetenschap, kunst, ambacht, België.',null,null,null,null,10000,'Flyer oproep 2025: beurzen van €10.000.','https://arba-esa.be/sites/default/files/2024-10/2024_VOCATIO_Flyer_Appel%202025_FR-NL.pdf'),
('060f1279-e4df-4f95-9c32-3e71bbfb9468','Het VriendenLoterij Fonds is een fonds op naam binnen Stichting DOEN dat koplopers steunt die werken aan een wereld waarin iedereen meedoet en er ruimte is voor radicale verbeelding. Het fonds financiert kunst- en cultuurprojecten die diep in de samenleving geworteld zijn, gemeenschappen betrekken via sociale praktijk, inclusief en horizontaal samenwerken, nieuwe gemeenschappen bereiken en streven naar blijvende verandering in plaats van eenmalige evenementen, met aandacht voor ecologische, sociale en culturele duurzaamheid. Disciplines: architectuur, beeldende kunst, erfgoed, audiovisueel, literatuur, muziek, design, podiumkunsten en digitale cultuur. Aanvragers zijn culturele organisaties en kunstenaars in het Koninkrijk der Nederlanden; reizen tussen Nederland en het Caribisch deel van het Koninkrijk komen in aanmerking. Doorlopend aanvragen, minimaal vier maanden voor start. Trefwoorden: sociale kunstpraktijk, community art, inclusie.',null,null,'Amsterdam',null,null,null,'https://dutchculture.nl/en/grant/vriendenloterij-fund-power-collective-imagination'),
('ab328ad4-e0f9-4f4a-8a3f-6629d7b1eb27','Het Yvonne van Gennip Talent Fonds helpt talentvolle kinderen en jongeren in Nederland financiële drempels te overwinnen, zodat zij zich kunnen ontwikkelen en kunnen deelnemen aan trainingen en wedstrijden. De nadruk ligt op erkend sporttalent, zowel TeamNL-talenten als veelbelovende sporters buiten TeamNL, met extra aandacht voor jonge sporters uit gezinnen met een laag inkomen. Het fonds werkt onder meer via de Talentvoorziening, die via sportbonden loopt en niet via open aanvragen, en via samenwerking met het Jeugdfonds Sport & Cultuur. Daarnaast is er het programma Missie 1 voor 100, waarin talenten zich inzetten voor een maatschappelijke uitdaging. Trefwoorden: sporttalent, talentontwikkeling, topsport, jeugdsport, financiële drempels, kansengelijkheid.',null,null,null,null,null,null,'https://www.kindora.co/en/funders/stichting-yvonne-van-gennip-talent-fonds'),
('63950d3b-2798-4bb6-93b2-20e740ba1e91','Adessium Foundation, opgericht in 2005, streeft naar een open samenleving waarin mensen volwaardig kunnen meedoen en hun rechten en vrijheden beschermd zijn. De stichting ondersteunt non-profitorganisaties met giften, advies en toegang tot haar netwerk binnen drie programma''s: Rechtvaardige en Gelijkwaardige Samenleving, Natuur en Leefomgeving, en Geïnformeerde Samenleving (onder meer onafhankelijke journalistiek en betrouwbare informatie). Een deel van het jaarbudget is gereserveerd voor initiatieven buiten deze programma''s, om in te spelen op onvoorziene ontwikkelingen en urgente noden. Werkgebied: Nederland en Europa. Belangrijk: er is geen open aanvraagprocedure; Adessium benadert potentiële partners zelf. Trefwoorden: open samenleving, rechtsstaat, mensenrechten, natuur, leefomgeving, journalistiek, informatievoorziening.','https://www.adessium.org','Adessium Foundation streeft naar een open samenleving waarin mensen volwaardig meedoen en hun rechten en vrijheden beschermd zijn.','Reeuwijk',null,null,null,'https://www.adessium.org/en/about-us/'),
('faedc214-dd9e-4550-bcf7-53f0338b3166','De Consular Club van Ho Chi Minh-stad is een netwerk van consulaire vertegenwoordigers en betrokkenen uit diplomatieke en zakelijke kringen dat geld inzamelt voor goede doelen in Zuid-Vietnam. Via een jaarlijks benefietdiner en een internationale liefdadigheidsbazaar, met veilingen en ticketverkoop, worden middelen geworven die naar geselecteerde goede doelen gaan. De club richt zich op kansarme kinderen, meisjes uit etnische minderheden en mensen in armoede. Eerdere steun ging onder meer naar beurzen voor wees- en gehandicapte kinderen, noodhulp na stormen en overstromingen en steun tijdens de coronapandemie. Begunstigden waren onder meer organisaties op het gebied van kinderbescherming, voedselherverdeling en empowerment van meisjes. Trefwoorden: Vietnam, kinderbescherming, meisjes, etnische minderheden, beurzen, noodhulp, armoede.',null,null,'Ho Chi Minh-stad',null,null,null,'https://www.epicurevietnam.com/events-1/vietnam/consular-club-hosts-annual-fundraising-dinner-in-a-glamorous-night-of-giving-back'),
('11e53f71-ba44-415f-9d20-c4d0071f5fe5','Het Direct Aid Program (DAP) Cambodja is een kleinschalig subsidieprogramma van de Australische ambassade in Phnom Penh, gefinancierd door het Australische ministerie van Buitenlandse Zaken en Handel (DFAT). Het programma draagt bij aan armoedebestrijding en duurzame ontwikkeling in Cambodja en bevordert de samenwerking tussen Australië en Cambodja. Prioriteiten zijn mensenrechten (waaronder gendergelijkheid en kansen voor minderheden), inclusief ondernemen met maatschappelijke impact, milieubeheer en duurzame ontwikkeling, en capaciteitsopbouw in STEM. Aanvragen kunnen komen van lokale en internationale ngo''s en instellingen die door de Cambodjaanse overheid erkend zijn; private partijen alleen voor activiteiten zonder winstoogmerk. Er zijn projectsubsidies en kleinere subsidies. Trefwoorden: ontwikkelingssamenwerking, armoedebestrijding, gendergelijkheid, minderheden, sociaal ondernemen, milieu, STEM, Cambodja.',null,null,'Phnom Penh',null,null,'Oproep 2019-20: kleine subsidies AUD 5.000–10.000, projectsubsidies AUD 15.000–25.000 (Australische dollars, niet omgerekend).','https://www2.fundsforngos.org/latest-funds-for-ngos/australian-embassy-in-phnom-penh-seeking-eois-for-direct-aid-program-dap-2019-20/amp/')
), u as (update public.funders f set
 algemene_beschrijving = coalesce(nullif(f.algemene_beschrijving,''), v.beschr),
 website = coalesce(nullif(f.website,''), v.website),
 missie = coalesce(nullif(f.missie,''), v.missie),
 plaats = coalesce(nullif(f.plaats,''), v.plaats),
 bijdrage_min = coalesce(f.bijdrage_min, v.bmin::numeric),
 bijdrage_max = coalesce(f.bijdrage_max, v.bmax::numeric),
 bijdrage_toelichting = coalesce(nullif(f.bijdrage_toelichting,''), v.btoel),
 bandbreedte_bijdrage_id = coalesce(f.bandbreedte_bijdrage_id, (select b.id from public.bandbreedtes_bijdrage b where coalesce(f.bijdrage_max, v.bmax::numeric) is not null and coalesce(f.bijdrage_max, v.bmax::numeric) > b.bedrag_min and (b.bedrag_max is null or coalesce(f.bijdrage_max, v.bmax::numeric) <= b.bedrag_max) order by b.volgorde limit 1)),
 research_source = coalesce(f.research_source,'') || case when f.research_source is null or f.research_source='' then '' else ' | ' end || 'Verrijking goedgekeurde fondsen ronde12, 17-10-2026 (Claude)',
 last_researched_at = now()
from v where f.id = v.id::uuid returning 1)
select count(*) bijgewerkt from u;